package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraftforge.common.ForgeConfigSpec;
import net.minecraftforge.fml.config.ModConfig;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class ConfigCatalogueDraftTest {
 enum Choice { FIRST, SECOND }
 private List<ConfigCatalog.Definition> fixture(){
  var b=new ForgeConfigSpec.Builder();b.push("storage");b.defineInRange("items",64000000L,1L,Long.MAX_VALUE);b.define("enabled",true);b.defineInRange("gain",.5d,0d,1d);b.defineEnum("mode",Choice.FIRST);b.defineList("ids",List.of("minecraft:stone"),o->o instanceof String);b.pop();
  String family="Test"+UUID.randomUUID();ConfigCatalog.capture(family,ModConfig.Type.SERVER,b.build(),"test.toml");return ConfigCatalog.definitions().stream().filter(d->d.family().equals(family)).toList();
 }
 private ConfigCatalog.Definition get(List<ConfigCatalog.Definition> ds,String name){return ds.stream().filter(d->d.path().get(1).equals(name)).findFirst().orElseThrow();}
 @Test void dynamicallyRegisteredValuesHaveNativePathsBoundsAndChoices(){var ds=fixture();assertEquals(5,ds.size());var d=get(ds,"items");assertEquals(List.of("storage","items"),d.path());assertEquals("1",d.minimum());assertEquals(Long.toString(Long.MAX_VALUE),d.maximum());assertEquals(List.of("FIRST","SECOND"),get(ds,"mode").choices());}
 @Test void longCapacityRetainsEveryBit(){var ds=fixture();var draft=new ConfigEditDraft(ds);var id=get(ds,"items").id();draft.set(id,"9223372036854775807");assertEquals(Long.MAX_VALUE,draft.current(id));assertEquals(64000000L,draft.original(id));assertEquals(64000000L,get(ds,"items").current());var serialized=draft.exportPreset(true);draft.cancel();draft.importPreset(serialized);assertEquals(Long.MAX_VALUE,draft.current(id));}
 @Test void invalidNumbersDoNotChangeDraft(){var ds=fixture();var draft=new ConfigEditDraft(ds);for(String invalid:List.of("9223372036854775808","1.5","-1"))assertThrows(IllegalArgumentException.class,()->draft.set(get(ds,"items").id(),invalid));for(String invalid:List.of("NaN","Infinity","-0.1","1.1"))assertThrows(IllegalArgumentException.class,()->draft.set(get(ds,"gain").id(),invalid));assertEquals(0,draft.changes());}
 @Test void resetUndoAndCancelDoNotSaveAnything(){var ds=fixture();var draft=new ConfigEditDraft(ds);String id=get(ds,"enabled").id();draft.set(id,"false");assertTrue(draft.changed(id));assertEquals(true,draft.expected().get(id));draft.reset(id);assertEquals(0,draft.changes());draft.set(id,"false");draft.undo(id);assertEquals(true,draft.current(id));draft.set(id,"false");draft.cancel();assertEquals(0,draft.changes());}
 @Test void presetValidationIsAtomicAndRejectsUnknownKeys(){var ds=fixture();var draft=new ConfigEditDraft(ds);String id=get(ds,"enabled").id();assertThrows(IllegalArgumentException.class,()->draft.importPreset("{\"schema\":1,\"values\":{\""+id+"\":false,\"unknown\":1}}"));assertEquals(0,draft.changes());assertThrows(IllegalArgumentException.class,()->draft.importPreset("{\"schema\":2,\"values\":{}}"));}
 @Test void presetsRejectTypeCoercion(){var ds=fixture();var draft=new ConfigEditDraft(ds);String id=get(ds,"enabled").id();assertThrows(IllegalArgumentException.class,()->draft.importPreset("{\"schema\":1,\"values\":{\""+id+"\":\"false\"}}"));assertEquals(0,draft.changes());}
 @Test void listAndEnumEditsUseNativeValidation(){var ds=fixture();var draft=new ConfigEditDraft(ds);draft.set(get(ds,"ids").id(),"[\"minecraft:dirt\"]");draft.set(get(ds,"mode").id(),"SECOND");assertEquals(Choice.SECOND,draft.current(get(ds,"mode").id()));assertThrows(IllegalArgumentException.class,()->draft.set(get(ds,"mode").id(),"THIRD"));assertThrows(IllegalArgumentException.class,()->draft.set(get(ds,"ids").id(),"[1]"));}
 @Test void remoteUpdatesDoNotSilentlyRebasePendingEdits(){var ds=fixture();var draft=new ConfigEditDraft(ds);String id=get(ds,"items").id();draft.set(id,"70000000");draft.observe(id,80000000L,false);assertEquals(64000000L,draft.original(id));assertEquals(70000000L,draft.current(id));draft.observe(id,80000000L,true);assertTrue(draft.changed(id));draft.observe(id,70000000L,true);assertFalse(draft.changed(id));assertEquals(70000000L,draft.original(id));}
 @Test void untouchedRemoteFieldsRefreshWithoutChangingOtherPendingFields(){var ds=fixture();var draft=new ConfigEditDraft(ds);String id=get(ds,"items").id(),gain=get(ds,"gain").id();draft.set(id,"70000000");draft.observe(gain,.75d,false);assertEquals(.75d,draft.current(gain));assertEquals(.75d,draft.original(gain));assertEquals(1,draft.changes());}
 @Test void detachedThirdPartyListsPreserveNativeElementTypesAndLongPrecision(){var b=new ForgeConfigSpec.Builder();b.defineListAllowEmpty("longs",List.of(Long.MAX_VALUE),o->o instanceof Long);b.defineListAllowEmpty("flags",List.of(true),o->o instanceof Boolean);var ds=ConfigCatalog.describe("external-fixture","external.toml",ModConfig.Type.CLIENT,b.build());var longs=ds.stream().filter(d->d.path().equals(List.of("longs"))).findFirst().orElseThrow();var flags=ds.stream().filter(d->d.path().equals(List.of("flags"))).findFirst().orElseThrow();assertEquals(List.of(Long.MAX_VALUE),longs.parse("[9223372036854775807]"));assertEquals(List.of(false,true),flags.parse("[false,true]"));assertThrows(IllegalArgumentException.class,()->flags.parse("[\"true\"]"));assertThrows(ArithmeticException.class,()->longs.parse("[9223372036854775808]"));}
 @Test void thirdPartyDefinitionsNeverBecomeOwnServerEditIds(){var b=new ForgeConfigSpec.Builder();b.define("enabled",true);var values=ConfigCatalog.describe("external-fixture-"+UUID.randomUUID(),"other.toml",ModConfig.Type.SERVER,b.build());assertEquals(1,values.size());assertNull(ConfigCatalog.find(values.get(0).id()));}
}
